"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import (InvalidRequest, Response, bad_request, not_found,
                                     require_positive_int)


class CustomerInsightsController:
    def __init__(self, orders: OrderService) -> None:
        self._orders = orders

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers ranked by lifetime value, highest first."""
        try:
            limit = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        return Response(200, {"customers": [
            {"customer_id": customer_id, "name": name, "lifetime_value_cents": value}
            for customer_id, name, value in self._orders.top_customers(limit)]})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and combined total of a customer's non-cancelled orders."""
        try:
            order_count, total_cents = self._orders.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": total_cents})

    def handle_order_history(self, customer_id: str) -> Response:
        """A customer's orders, newest first, with the total the order summary reports."""
        try:
            summaries = self._orders.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {
            "customer_id": customer_id,
            "orders": [{"order_id": s.order.order_id, "status": s.order.status,
                        "total_cents": s.total_cents} for s in summaries],
        })

