def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_no_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert (response.status, response.body) == (200, {"customer_id": "c1", "orders": []})


def test_history_newest_first_with_cancelled_and_discount_totals(shop):
    first = order(shop, "c2", ("BOOK", 2)).body["order_id"]
    second = order(shop, "c2", ("LAMP", 1)).body["order_id"]
    order(shop, "c1", ("PEN", 1))
    shop.orders.handle_cancel(first)

    response = shop.insights.handle_order_history("c2")
    assert response.status == 200
    assert response.body["customer_id"] == "c2"
    assert [o["order_id"] for o in response.body["orders"]] == [second, first]
    assert [o["status"] for o in response.body["orders"]] == ["placed", "cancelled"]
    for entry in response.body["orders"]:
        assert entry["total_cents"] == shop.orders.handle_get(entry["order_id"]).body["total_cents"]


def test_lifetime_value_unknown_customer(shop):
    response = shop.insights.handle_lifetime_value("nobody")
    assert (response.status, response.body) == (404, {"error": "customer not found"})


def test_lifetime_value_no_orders(shop):
    response = shop.insights.handle_lifetime_value("c1")
    assert response.body == {"customer_id": "c1", "order_count": 0, "lifetime_value_cents": 0}


def test_lifetime_value_excludes_cancelled_and_uses_discounted_totals(shop):
    first = order(shop, "c2", ("BOOK", 2)).body["order_id"]
    second = order(shop, "c2", ("LAMP", 1)).body["order_id"]
    third = order(shop, "c2", ("PEN", 3)).body["order_id"]
    order(shop, "c1", ("PEN", 1))
    shop.orders.handle_cancel(first)

    expected = sum(shop.orders.handle_get(o).body["total_cents"] for o in (second, third))
    response = shop.insights.handle_lifetime_value("c2")
    assert response.status == 200
    assert response.body == {"customer_id": "c2", "order_count": 2, "lifetime_value_cents": expected}


