def test_top_customers_ranking_ties_zero_and_limit(shop):
    for cid, name in (("b1", "Bea"), ("a1", "Abe"), ("z0", "Zed"), ("c3", "Cy")):
        shop.customers.handle_register({"customer_id": cid, "name": name, "email": f"{cid}@example.com"})
    order(shop, "b1", ("BOOK", 1))
    order(shop, "a1", ("BOOK", 1))
    order(shop, "c1", ("LAMP", 1))
    order(shop, "c3", ("PEN", 1))
    shop.orders.handle_cancel(order(shop, "z0", ("LAMP", 2)).body["order_id"])
    # c2 has only a cancelled order too, so it is excluded.
    shop.orders.handle_cancel(order(shop, "c2", ("BOOK", 1)).body["order_id"])

    body = shop.insights.handle_top_customers(10).body
    assert body == {"customers": [
        {"customer_id": "c1", "name": "Ada", "lifetime_value_cents": 6_000},
        {"customer_id": "a1", "name": "Abe", "lifetime_value_cents": 2_500},
        {"customer_id": "b1", "name": "Bea", "lifetime_value_cents": 2_500},
        {"customer_id": "c3", "name": "Cy", "lifetime_value_cents": 300},
    ]}
    limited = shop.insights.handle_top_customers(2).body["customers"]
    assert [c["customer_id"] for c in limited] == ["c1", "a1"]
    for entry in body["customers"]:
        assert entry["lifetime_value_cents"] == shop.insights.handle_lifetime_value(
            entry["customer_id"]).body["lifetime_value_cents"]
